    "open_answer": "",
    "explanation": "Hematopoezde **lenfositler** (B, T ve NK hücreleri) **lenfoid progenitörden** köken alır; miyeloid kök hücreden türemez. Eritrosit, granülosit, monosit ve trombositler ise miyeloid kök hücre serisinden gelişir.",
