    "professor": "Belirtilmemiş",
    "question": "Miyofibriller membranöz bir tübül sistemi olan sarkoplazmik retikulum ile çevrilidir. Özelleşmiş bir endoplazmik türüdür. Yapısal olarak düz ve tanecikli ER'den farkı nedir?",
