    "question": "Aşağıdakilerden hangisi Protrombin Aktivatörünün tam karşılığıdır?",
    "options": [
      {
        "letter": "A",
        "text": "aF10 + aF5 + Kalsiyum + Fosfollplt"
      },
      {
        "letter": "B",
        "text": "aFIO + aF5 + Kalsiyum + Fosfolipit + F3"
      },
      {
        "letter": "C",
        "text": "aF10 + aF5 + Kalsiyum + Fosfolipit + F7"
      },
      {
        "letter": "D",
        "text": "aF10 + aF5 + Kalsiyum + Fosfolipit + FB"
      },
      {
        "letter": "E",
        "text": "aF10 + aF5 + Kalsiyum 4 Fosfolipit +"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Koagülasyon kaskadında protrombini (Faktör II) aktif trombine (Faktör IIa) dönüştüren **protrombin aktivatörü (protrombinaz kompleksi)**; aktif Faktör Xa (**aF10**), kofaktörü aktif Faktör Va (**aF5**), **kalsiyum (Ca2+)** iyonları ve trombosit/doku yüzeyi **fosfolipitlerinden** oluşur (A doğru). F3 (doku faktörü / tromboplastin) ekstrensek yolağın başlangıcında Faktör VIIa ile kompleks kurar, protrombin aktivatör kompleksinin bileşeni değildir (B yanlış). F7 (prokonvertin) ekstrensek yolağın aktivasyonunda doku faktörüyle birlikte Faktör X'u aktive eder, protrombinazın doğrudan parçası değildir (C yanlış). F8 (antihemofilik faktör A) intrensek tenaz kompleksinde Faktör IXa'nın kofaktörüdür; protrombinaz kompleksinde yer almaz (D yanlış). Eksik veya kesik yazılmış olan bu seçenekte temel protrombinaz bileşenlerinin dışında fazladan bir '+' unsuru yer aldığından protrombin aktivatörünün tam karşılığını ifade etmez (E yanlış).",
