    "subject": "Histoloji ve Embriyoloji",
    "professor": "Sinan Yürüker",
    "question": "Diskus interkalaris için aşağıdakilerden hangileri doğrudur?\nI. Kalp kasında bulunur.\nII. Zonula adherens içerir.\nIII. Oluklu bağlantı (gap junction) içerir.\nIV. Zonula okludens içerir.\nV. Fasya adherens içerir.",
    "options": [
      {
        "letter": "A",
        "text": "I + II"
      },
      {
        "letter": "B",
        "text": "IV + V"
      },
      {
        "letter": "C",
        "text": "I + III + V"
      },
      {
        "letter": "D",
        "text": "III + IV"
      },
      {
        "letter": "E",
        "text": "II + III"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Yalnızca kalp kasında bulunan **diskus interkalaris** (I), hücreleri boyuna eksende elektriksel olarak bağlayan **oluklu bağlantıları (gap junction)** (III) ve enine eksende mekanik tutunma sağlayan **fasya adherensi** (V) içerir; bu nedenle I + III + V birleşimi doğrudur (C doğru). I öncülü doğru olmasına karşın II öncülündeki zonula adherens epitel hücrelerini çepeçevre saran kemer biçimli bağlantı olup kalp kasında bunun yerini **fasya adherens** alır (A yanlış). V öncülü doğru olmakla birlikte IV öncülündeki zonula okludens (sıkı bağlantı) epitel dokusuna özgüdür ve diskus interkalariste bulunmaz (B yanlış). III öncülü doğru olsa da IV öncülündeki zonula okludens diskus interkalarisin yapısında yer almaz ve I ile V öncülleri eksiktir (D yanlış). III öncülü doğru olmasına rağmen II öncülündeki zonula adherens diskus interkalariste değil epitel dokusunda bulunur (E yanlış).",
    "note": "Hatırlanan 4 şıklı sorudan 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
