    "explanation": "**Musculus risorius** (n. facialis), ağız köşesini dış yana doğru çekerek tebessüm ifadesi oluşturan mimik kasıdır. M. zygomaticus major ise ağız köşesini yukarı ve dışa çekerek gülmeyi sağlar.",
