    "explanation": "**Musculus pectoralis major**, toraks ön duvarından başlayıp humerus'ta crista tuberculi majoris'e tutunarak kola güçlü **adduksiyon**, fleksiyon ve iç rotasyon yaptıran temel kastır.",
