    "explanation": "Funiculus spermaticus içinde n. genitofemoralis'in ramus genitalis'i yer alır; **ramus femoralis** kılıfa girmez, lacuna vasorum'dan geçerek uyluk ön-üst derisinin duyusunu alır.",
    "note": "",
