    "question": "Çizgili iskelet kası ve kalp kasında kasılma sırasında gerçekleşen;\nI. Sarkoplazmik retikulumdan Ca2+ salınımı\nII. Kas liflerinde aksiyon potansiyeli oluşumu\nIII. Troponin C - kalsiyum kompleksi oluşumu\nIV. Tropomiyozinin yoldan çekilmesi ve miyozin başının F-aktin ile etkileşmesi\nolaylarının doğru sıralaması aşağıdakilerden hangisidir?",
