    "subject": "Fizyoloji",
    "professor": "Belirtilmemiş",
    "question": "Aşağıdaki yapıların hangisinde  parasempatik inenrasvon bulunmaz?",
    "options": [
      {
        "letter": "A",
        "text": "Gastrointestinal sistem"
      },
      {
        "letter": "B",
        "text": "Erektil organ damarları"
      },
      {
        "letter": "C",
        "text": "Çizgili kas damarları"
      },
      {
        "letter": "D",
        "text": "Ventrikül myokardı"
      },
      {
        "letter": "E",
        "text": "Ter bezleri"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Ekrin **ter bezleri**, anatomik olarak sempatik zincirden çıkan kolinerjik postganglionik sempatik liflerle innerve edilir; vücutta **parasempatik innervasyonu bulunmayan** yapılar arasındadır.",
    "note": "",
    "q_type": "mcq",
