    "subject": "Anatomi",
    "professor": "Mahmut Çay",
    "question": "KOIunu 90 kadar kaldırabilen bir hastaya elini başının üstüne getirmesi İstendiği zaman devam ettiremediği gözlenmiştir. Bu kişinin hangi siniri zedelenmiş ve hangi kası felç olmuştur?",
