    "open_answer": "",
    "explanation": "Kolun 90 derecenin üzerine kaldırılmasında (hiperabduksiyon) skapulaya dış rotasyon yaptıran **m. serratus anterior (n. thoracicus longus)** kası görev alır; bu kasın felcinde kol baş üstüne kaldırılamaz.",
    "note": "",
