    "professor": "Mahmut Çay",
    "question": "Apandisit ameliyatı geçiren bir hastada post-op fıtıklaşma görülmüştür. Apendektomi esnasında bu hastanın hangi sinirinin hasar görme ihtimali yüksektir?",
