    "subject": "Fizyoloji",
    "professor": "Arzu Şahin",
    "question": "Aşağıdaki bilgilerden hangisi kan basıncı ölçümü yapılırken dikkat edilecek c LAB) noktalar için doğru bir ifadedir?",
    "options": [
      {
        "letter": "A",
        "text": "Hastanın kolunun basıncın etkisiyle ağrımamasını önlemek için manşetin altında giysi olmamalıdır."
      },
      {
        "letter": "B",
        "text": "Kadınlarda mastektomi (memenin tamamen çıkartılması) geçirmiş taraftan ölçüm yapılmaz.- Doğru Seçenek"
      },
      {
        "letter": "C",
        "text": "Steteskop, manşetin altına düzenli bir şekilde yerleştirilmelidir."
      },
      {
        "letter": "D",
        "text": "Ölçüm yapılan kol kalp hizasından 3 parmak yukarıda olmalıdır."
      },
      {
        "letter": "E",
        "text": "Stetoskop brakiyal nabzın en iyi alındığı noktaya yerleştirilerek sesi net duymak için steteskopun üzerinden çok iyi bastırılmalıdır."
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Mastektomi ve aksiller lenf nodu diseksiyonu geçirmiş taraftaki kolda lenfatik drenaj bozulduğundan manşon basıncı venöz staza ve ciddi lenfödem gelişimine yol açabilir; bu nedenle **mastektomi geçirmiş taraftan kan basıncı ölçümü yapılmaz** (B doğru). Manşetin altında giysi bulunmamasının temel gerekçesi ağrıyı önlemek değil, kumaş katmanlarının basıncı dağıtarak yanlış yüksek veya hatalı ölçüm oluşturmasını engellemektir (A yanlış). Stetoskop manşetin altına sıkıştırılmamalıdır; manşon antekübital fossanın 2-3 cm üzerine sarılmalı ve stetoskop diyaframı manşetin hemen altına, açıkta kalan brakiyal arter üzerine yerleştirilmelidir (C yanlış). Hidrostatik sütun hatasını önlemek için ölçüm yapılan kol kalp hizasından 3 parmak yukarıda değil **tam kalp hizasında** (4. interkostal aralık düzeyinde) tutulmalıdır (D yanlış). Stetoskop brakiyal arter üzerine çok güçlü bastırılırsa arter mekanik olarak sıkışıp yapay türbülans sesleri doğurur ve diyastolik değer olduğundan düşük ölçülür; stetoskop hafifçe temas ettirilmelidir (E yanlış).",
