    "professor": "Arzu Şahin",
    "question": "FizyoIojik görevlerinden biri; allerjik durumlarda mast hücreleri ve bazofillerden salgılanan heparin,histamin gibi maddeleri inaktive ederek, allerjen antikor kompleksini yıkıp yerel inflamasyon sürecinin yayılmasını önlemek olan lökosit türü aşağıdakilerden hangisidir?",
