    "professor": "Arzu Şahin",
    "question": "TuberküIoz, Lepra gibi kalın lipid tabakası olan basillere etkili olan lipaz enzimini bulunduran ve bu nedenle Tüberküloz, Lepra basillerinin membranını parçayabilen kan hücresi aşağıdakilerden hangisidir?",
