    "q_num": 82,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Sinan Yürüker",
    "question": "Sinir sistemine ait aşağıdaki hücrelerden hangisi kemik iliği kökenlidir?",
    "options": [
      {
        "letter": "A",
        "text": "MikrogIiya"
      },
      {
        "letter": "B",
        "text": "Astrosit"
      },
      {
        "letter": "C",
        "text": "Oligodendrosit"
      },
      {
        "letter": "D",
        "text": "Schwann hücresi"
      },
      {
        "letter": "E",
        "text": "Stellat hücre"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Santral sinir sistemindeki diğer nöron ve glia hücreleri ektodermden gelişirken; beynin yerleşik makrofajları olan **mikrogliya hücreleri mezodermden (kemik iliği mononükleer fagosit serisinden)** köken alır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
