    "question": "Kemik iliğinde hematopoetik aktivite ilk olarak hangi kemikte izlenir.",
    "options": [
      {
        "letter": "A",
        "text": "KlavikuIa"
      },
      {
        "letter": "B",
        "text": "Humerus"
      },
      {
        "letter": "C",
        "text": "Femur"
      },
      {
        "letter": "D",
        "text": "Skapula"
      },
      {
        "letter": "E",
        "text": "Frontal kemik bulunan \"Malpighi tabakası\""
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Fetal gelişimde vücutta kemikleşmeyi ilk başlatan kemik olan **klavikula (köprücük kemiği)**, kemik iliğinde hematopoetik aktivitenin ilk gözlendiği kemiktir.",
