    "professor": "Sinan Yürüker",
    "question": "hangi katlardan oluşur?l. Stratum basale,ll. stratum spinosumlll. Stratum granuIosumIV. Stratum lusidumV. Stratum korneum",
    "options": [
      {
        "letter": "A",
        "text": "1+11"
      },
      {
        "letter": "B",
        "text": "11+111"
      },
      {
        "letter": "C",
        "text": "II+IV"
      },
      {
        "letter": "D",
        "text": "1+111"
      },
      {
        "letter": "E",
        "text": "III+V"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Epidermisin canlı ve bölünebilen Malpighi tabakası; kök hücrelerin bulunduğu **stratum basale** (I) ile birbirine desmozomlarla tutunan hücrelerin oluşturduğu **stratum spinosum** (II) katmanlarından oluşur.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
