    "subject": "Anatomi",
    "professor": "M. Haluk Uluutku",
    "question": "Yürüyüş sırasında  sol crus'unu extansiyona getieremediği için eliyle dizine bastırarak bu işlemi yapıp yürümeye çalışan hastada hangi sinirin lezyonunu düşünürsünüz?",
