    "answer": "E",
    "open_answer": "",
    "explanation": "Dizin temel ekstansör kası m. quadriceps femoris'i **nervus femoralis** innerve eder; hasarında hasta bacağına ekstansiyon yaptıramaz ve yığılmayı önlemek için eliyle dizine bastırarak yürümeye çalışır.",
    "note": "",
    "q_type": "mcq",
