    "explanation": "Çizgili kasta uyarılma; nöromusküler kavşakta aksiyon potansiyeli oluşumu, sarkolemmada yayılma, T-tübülü iletimi, SR'den Ca²⁺ salınımı ve Ca²⁺'un troponin C'ye bağlanması sırasını izler.",
