    "explanation": "Periferik bir akson kesildiğinde veya ezildiğinde, lezyon düzeyinin distalinde kalan akson segmenti ve miyelin kılıfının yıkılıp temizlenmesi sürecine **Wallerian dejenerasyonu** denir.",
    "note": "",
