    "year": "2023-2024",
    "q_num": 11,
    "subject": "Anatomi",
    "professor": "M. Haluk Uluutku",
    "question": "Erb-duchenne tipi paralizide etkilenen spinal sinir koklerini veren sikki seciniz",
    "options": [
      {
        "letter": "A",
        "text": "Cervikal 5. spinal sinir koku"
      },
      {
        "letter": "B",
        "text": "Cervikal 6. spinal sinir koku"
      },
      {
        "letter": "C",
        "text": "Cervikal 5 ve 6. spinal sinir koku"
      },
      {
        "letter": "D",
        "text": "Cervikal 7. spinal sinir koku"
      },
      {
        "letter": "E",
        "text": "Cervikal 8 ve thoracal 1. spinal sinir koku"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "**Erb-Duchenne tipi paralizi**, plexus brachialis'in üst trunkusunu oluşturan **servikal 5 ve 6. (C5-C6) spinal sinir köklerinin** baş ile omuz arasındaki açının zorla genişlemesine bağlı gerilme veya kopmasıyla oluşur ve üst ekstremitede addüksiyon-iç rotasyon-önkol pronasyonu ('bahşiş isteyen el') tablosuna yol açar (C doğru). Tek başına servikal 5. spinal sinir kökü üst trunkusun tümünü oluşturmaz; Erb noktası C5 ve C6 köklerinin birleştiği üst trunkus bölgesidir (A yanlış). Yalnızca servikal 6. spinal sinir kökü hasarı C5'ten gelen omuz abduksiyon ve dış rotasyon liflerinin kaybını tek başına karşılamaz (B yanlış). Servikal 7. spinal sinir kökü plexus brachialis'in orta trunkusunu oluşturur ve klasik Erb-Duchenne paralizisinin ana lezyon yeri değildir (D yanlış). Servikal 8 ve torakal 1. (C8-T1) spinal sinir köklerinin tutulumu üst trunkus felcine değil, elin küçük kaslarını felç edip pençe el yapan **Klumpke paralizisine** neden olur (E yanlış).",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": "",
