    "professor": "Sinan Yürüker",
    "question": "Hangisi diskus interkalaris için yanlıştır?I- Kalp kasında bulunur.II- Zonula adherens içerirIII- Oluklu bağlantı (gap junction) içerir.IV. Zonula okludens içerirV. Fasya",
