    "question": "Aksiller lenf nodu diseksiyonu sonrası saçını tarayamayan, kolunu 90 derecenin üzerine kaldıramayan ve sırtta kanat skapula (winged scapula) deformitesi gelişen bir hastada hangi sinir ve kas hasarlanmıştır?",
