    "answer": "E",
    "open_answer": "M. tibialis anterior (ve M. tibialis posterior)",
    "explanation": "Ayağa primer **inversiyon** (ayak tabanının mediale/içe döndürülmesi) yaptıran başlıca kaslar ön kompartmandaki **m. tibialis anterior** (n. fibularis profundus) ile derin arka kompartmandaki **m. tibialis posterior** (n. tibialis) olup bu hareketin kaybında öncelikle bu iki kas düşünülür (E doğru). M. extensor digitorum longus ve m. fibularis tertius ayağa dorsifleksiyonla birlikte **eversiyon** yaptırır, inversiyon değil (A yanlış). M. gastrocnemius ve m. soleus (m. triceps surae) tendo calcaneus aracılığıyla ayağın güçlü primer plantar fleksörleridir, primer inversiyon yaptırmazlar (B yanlış). M. flexor digitorum longus parmak fleksiyonuna ve zayıf plantar fleksiyona katılır, m. plantaris ise çok zayıf bir plantar fleksördür; primer inversör çift değildirler (C yanlış). M. fibularis longus ve m. fibularis brevis ayağın primer **eversiyon** (tabanın dışa çevrilmesi) kaslarıdır, inversiyonun zıttı hareketi yaparlar (D yanlış).",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
