    "open_answer": "M. psoas major'un medial kenarından çıkar.",
    "explanation": "Plexus lumbalis'in L2-L4 ön dallarından oluşan **nervus obturatorius**, sinir ağının diğer büyük dallarından farklı olarak m. psoas major'un **medial kenarından** çıkarak linea terminalis boyunca küçük pelvise iner ve canalis obturatorius'tan uyluğun adduktor kompartmanına geçer (C doğru). M. psoas major'un lateral kenarından çıkanlar n. obturatorius değil; n. iliohypogastricus, n. ilioinguinalis, n. cutaneus femoris lateralis ve n. femoralis'tir (A yanlış). N. obturatorius kasın arkasındaki derin fasyada seyretmez; psoas major'un medial kenarından pelvik duvara doğru belirgin bir sinir gövdesi olarak ilerler (B yanlış). M. psoas major'un ön yüzünü delerek çıkan sinir n. obturatorius değil, L1-L2 köklerinden köken alan **n. genitofemoralis**'tir (D yanlış). M. iliacus ile m. psoas major arasındaki oluktan geçip ligamentum inguinale altından uyluğa giren sinir **n. femoralis**'tir, n. obturatorius değil (E yanlış).",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
