    "explanation": "Karın ön duvarı yüzeyel fasyasının (Scarpa fasyası) devamı olan **tunica dartos**, düz kas lifleri içerir ve soğukta büzüşüp testisleri vücuda yaklaştırarak testis ısısının korunmasını sağlar.",
